export default "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Utsuho preview</title>\n<style>\n:root{--bg:#fdfdfd;--muted:#a3a8ae;color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}\n*{box-sizing:border-box}\nhtml,body{height:100%;margin:0;overflow:hidden}\nbody{background:var(--bg);font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;-webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none}\n#stage{position:fixed;inset:0;cursor:pointer;touch-action:manipulation}\ncanvas{display:block;width:100%;height:100%}\n#hint{position:fixed;bottom:calc(env(safe-area-inset-bottom,0px) + 22px);left:0;right:0;text-align:center;font-size:.85rem;color:var(--muted);pointer-events:none}\n</style>\n<style>#aviso{position:fixed;left:0;right:0;top:50%;transform:translateY(-50%);height:190px;background:url(data:image/gif;base64,) repeat-x center/auto 190px;display:none;align-items:center;justify-content:center;font:900 3rem system-ui,sans-serif;color:#000;z-index:30;pointer-events:none}#probar{position:fixed;right:14px;bottom:calc(env(safe-area-inset-bottom,0px) + 14px);z-index:20;padding:10px 14px;border:0;border-radius:10px;background:#333;color:#fff;font-size:.9rem}</style><style>#hint{display:none!important}#boom{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:100vw;height:auto;display:none;pointer-events:none;z-index:35}</style></head>\n<body>\n<div id=\"stage\"></div>\n<div id=\"hint\">Cargando modelo\u2026</div>\n<script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/build/three.min.js\"></script>\n<script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/loaders/GLTFLoader.js\"></script>\n<script>\nconst GLB=\"\";\nconst TEX=[\"data:image/jpeg;base64,\"];\nconst MP3=\"data:audio/mpeg;base64,\";\nconst hint=document.getElementById('hint'),stage=document.getElementById('stage');\nfunction toBuf(s){const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u.buffer}\nconst renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});\nrenderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));\nrenderer.outputEncoding=THREE.sRGBEncoding;\nstage.appendChild(renderer.domElement);\nconst scene=new THREE.Scene();\nconst camera=new THREE.PerspectiveCamera(35,1,0.1,100);\nscene.add(new THREE.AmbientLight(0xffffff,0.9));\nconst dl=new THREE.DirectionalLight(0xffffff,0.8);dl.position.set(2,4,3);scene.add(dl);\nconst pivot=new THREE.Group();scene.add(pivot);const sg=new THREE.Group();const U={uAmp:{value:0},uBase:{value:0},uH:{value:1},uDrop:{value:0},uWide:{value:1}};\nconst audio=new Audio(MP3);audio.loop=false;audio.addEventListener('ended',function(){audio.currentTime=10;audio.play().catch(function(){});});audio.preload='auto';\nlet playing=false,t=0,last=performance.now(),radius=1,amp=0.1,ready=false;\nfunction fit(){\n  const w=stage.clientWidth||window.innerWidth,h=stage.clientHeight||window.innerHeight;\n  renderer.setSize(w,h,false);camera.aspect=w/h;\n  const v=camera.fov*Math.PI/180,hf=2*Math.atan(Math.tan(v/2)*camera.aspect);\n  const d=radius*0.6/Math.sin(Math.min(v,hf)/2);\n  camera.position.set(0,radius*0.15,d);camera.lookAt(0,0,0);camera.updateProjectionMatrix();\n}\nwindow.addEventListener('resize',fit);\nnew THREE.GLTFLoader().parse(toBuf(GLB),'',gltf=>{\n  const m=gltf.scene,box=new THREE.Box3().setFromObject(m),size=box.getSize(new THREE.Vector3());\n  const s=2/Math.max(size.x,size.y,size.z);m.scale.setScalar(s);\n  const b2=new THREE.Box3().setFromObject(m),c=b2.getCenter(new THREE.Vector3());\n  const tl=new THREE.TextureLoader();\n  const ld=(u,srgb)=>{const x=tl.load(u,()=>{});x.flipY=false;if(srgb)x.encoding=THREE.sRGBEncoding;x.anisotropy=4;return x};\n  const mat=new THREE.MeshBasicMaterial({map:ld(TEX[0],true),side:THREE.DoubleSide});mat.onBeforeCompile=sh=>{Object.assign(sh.uniforms,U);sh.vertexShader='uniform float uAmp;uniform float uBase;uniform float uH;uniform float uDrop;uniform float uWide;\\n'+sh.vertexShader.replace('#include <project_vertex>','vec4 wpos=modelMatrix*vec4(transformed,1.0);float kk=(wpos.y-uBase)/uH;wpos.y+=uAmp*smoothstep(0.0,0.85,kk);wpos.xz*=uWide;wpos.y-=uDrop;vec4 mvPosition=viewMatrix*wpos;gl_Position=projectionMatrix*mvPosition;')};\n  m.traverse(o=>{if(o.isMesh)o.material=mat});\n  m.position.sub(c);const hh=b2.getSize(new THREE.Vector3()).y/2;m.position.y+=hh;sg.position.y=-hh;sg.add(m);pivot.add(sg);U.uBase.value=-hh;U.uH.value=2*hh;m.traverse(o=>{o.frustumCulled=false});\n  radius=b2.getSize(new THREE.Vector3()).length()/2;amp=radius*0.15;\n  ready=true;fit();hint.textContent='Toca para girar y escuchar';\n},e=>{hint.textContent='No se pudo cargar el modelo: '+((e&&e.message)||e);console.error(e)});\nfunction toggle(){\n  if(!ready)return;\n  playing=!playing;last=performance.now();\n  if(playing&&!window.noMusic){if(audio.currentTime<10)audio.currentTime=10;audio.play().catch(()=>{});hint.textContent='Toca para pausar'}\n  else{audio.pause();hint.textContent='Toca para girar y escuchar'}\n}\nvar clicks=0;stage.addEventListener('click',function(){clicks++;if(clicks===14){window.noMusic=true;audio.pause();var a=document.getElementById('aviso');a.style.display='flex';al.currentTime=0;al.play().catch(function(){});setTimeout(function(){a.style.display='none'},10000);setTimeout(function(){var bo=document.getElementById('boom');bo.currentTime=0;bo.style.display='block';bo.onended=function(){bo.style.display='none';if(window.ReactNativeWebView){window.ReactNativeWebView.postMessage('close')}};bo.play().catch(function(){});},4000)}toggle();});\nfit();\n(function loop(now){\n  requestAnimationFrame(loop);\n  if(playing){t+=(now-last)/1000}\n  last=now;\n  pivot.rotation.y=-t*0.72;\n  const p=(t*2.55)%1;let h,dp=0;if(p<0.36){const u=p/0.36;h=0.5+0.5*Math.cos(Math.PI*u);dp=Math.sin(Math.PI*u)}else{const u=(p-0.36)/0.64;h=0.5-0.5*Math.cos(Math.PI*u)}U.uAmp.value=0.12*U.uH.value*h;U.uDrop.value=0.012*U.uH.value*dp;U.uWide.value=1+0.02*dp;\n  renderer.render(scene,camera);\n})(performance.now());\n</script>\n<video id=\"boom\" playsinline src=\"data:video/mp4;base64,\"></video><div id=\"aviso\"></div><script>const ALARM=\"data:audio/mpeg;base64,\";const al=new Audio(ALARM);if(0)document.getElementById(\"probar\").onclick=function(e){e.stopPropagation();al.currentTime=0;al.play().catch(function(){});var a=document.getElementById(\"aviso\");a.style.display=\"flex\";setTimeout(function(){a.style.display=\"none\"},4000)};</script></body>\n</html>\n";
